    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            size_ = other.size_; data_ = other.data_;
            other.size_ = 0; other.data_ = nullptr;
        }
        return *this;
    }
    int& operator[](std::size_t index) { return data_[index]; }
    std::size_t size() const { return size_; }
